#!/bin/bash
# SayurLogi Deploy Script - Payment Verification + WA Notifications
# Applies 12 patches for: manual payment verification flow + admin WA notif
set -e
cd ~/sayurlogi

echo "=== SayurLogi Deploy: 12 patches ==="

# Each patch as base64 (decoded + applied individually)
declare -A PATCHES

PATCHES[01]=""
PATCHES[02]=""
PATCHES[03]=""
PATCHES[04]=""
PATCHES[05]=""
PATCHES[06]=""
PATCHES[07]=""
PATCHES[08]=""
PATCHES[09]=""
PATCHES[10]=""
PATCHES[11]=""
PATCHES[12]=""

for i in 01 02 03 04 05 06 07 08 09 10 11 12; do
  echo "--- Patch $i ---"
  echo "${PATCHES[$i]}" | base64 -d > /tmp/patch-$i.patch
  if git apply --check /tmp/patch-$i.patch 2>/dev/null; then
    git apply /tmp/patch-$i.patch
    echo "✓ patch $i applied"
  else
    echo "⚠ patch $i check failed (may already be applied or conflict)"
    # Try apply anyway with --3way
    git apply --3way /tmp/patch-$i.patch 2>/dev/null && echo "✓ patch $i applied (3way)" || echo "✗ patch $i SKIPPED"
  fi
  rm -f /tmp/patch-$i.patch
done

echo ""
echo "=== All patches processed ==="
echo "Modified files:"
git status --short | grep "^ M" | head -15
echo ""
echo "Next: bun run build && pm2 restart sayurlogi"
